// Generated by Google Stitch, 3 August 2026. Source folder: 6-all_amenities
//
// WIRED 16 August 2026, task #116.
//
// Was five hardcoded groups with a fixed included/not-included pattern, shown
// identically for every property — a listing with no garden still showed
// "Garden" ticked, and "Shampoo" was struck through whether or not the host
// had provided it.
//
// It now takes a listingId, loads the property, and ticks exactly what the
// host selected. The groups and their order come from the shared catalogue in
// models/stay_amenities.dart, which mirrors the host wizard, so a group added
// on one side cannot go missing on the other.
//
// The back arrow was a bare Icon, not a button. Same fault as screen 01.
import 'package:flutter/material.dart';
import 'package:google_fonts/google_fonts.dart';

import '../models/stay_amenities.dart';
import '../models/stay_listing.dart';
import '../services/stay_listing_service.dart';
import '../theme/stay_colors.dart';

class AmenitiesFullScreen extends StatefulWidget {
  const AmenitiesFullScreen({super.key, required this.listingId});

  final String listingId;

  @override
  State<AmenitiesFullScreen> createState() => _AmenitiesFullScreenState();
}

class _AmenitiesFullScreenState extends State<AmenitiesFullScreen> {
  late final Future<StayListing?> _listing =
      StayListingService.instance.byId(widget.listingId);

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: Colors.white,
      appBar: AppBar(
        backgroundColor: Colors.white,
        elevation: 0.5,
        leading: IconButton(
          icon: const Icon(Icons.arrow_back, color: GoOutsColors.primaryBlue),
          onPressed: () => Navigator.of(context).pop(),
        ),
        title: Text(
          'Amenities',
          style: GoogleFonts.inter(
            fontSize: 20,
            fontWeight: FontWeight.w700,
            color: GoOutsColors.deepNavy,
          ),
        ),
      ),
      body: FutureBuilder<StayListing?>(
        future: _listing,
        builder: (context, snapshot) {
          if (snapshot.connectionState == ConnectionState.waiting) {
            return const Center(child: CircularProgressIndicator());
          }

          final StayListing? listing = snapshot.data;
          if (snapshot.hasError || listing == null) {
            return Center(
              child: Padding(
                padding: const EdgeInsets.all(32),
                child: Text(
                  'The amenities for this property could not be loaded.',
                  textAlign: TextAlign.center,
                  style: GoogleFonts.inter(
                      fontSize: 15, color: GoOutsColors.bodyText),
                ),
              ),
            );
          }

          final Set<String> has = listing.amenities.toSet();

          // Anything the host selected that this build does not recognise.
          // Listed under its own heading rather than dropped, so a newly added
          // host-side amenity is visible before the consumer app catches up.
          final List<String> unknown = listing.amenities
              .where((s) => !stayAmenitiesAll.any((a) => a.slug == s))
              .toList(growable: false);

          return ListView(
            padding: const EdgeInsets.all(16),
            children: [
              for (final entry in stayAmenityGroups.entries)
                _buildAmenityGroup(entry.key, entry.value, has),
              if (unknown.isNotEmpty)
                _buildAmenityGroup(
                  'Also available',
                  unknown.map(stayAmenityFor).toList(growable: false),
                  has,
                ),
            ],
          );
        },
      ),
    );
  }

  Widget _buildAmenityGroup(
    String title,
    List<StayAmenity> items,
    Set<String> has,
  ) {
    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        Padding(
          padding: const EdgeInsets.symmetric(vertical: 16),
          child: Text(
            title,
            style: GoogleFonts.inter(
              fontSize: 15,
              fontWeight: FontWeight.w700,
              color: GoOutsColors.primaryBlue,
            ),
          ),
        ),
        ...items.map((a) => _buildAmenityItem(a, has.contains(a.slug))),
        const Divider(),
      ],
    );
  }

  Widget _buildAmenityItem(StayAmenity amenity, bool isIncluded) {
    return Padding(
      padding: const EdgeInsets.symmetric(vertical: 12),
      child: Row(
        children: [
          Icon(
            isIncluded ? Icons.check : Icons.close,
            color: isIncluded
                ? GoOutsColors.tealSecondary
                : GoOutsColors.error.withValues(alpha: 0.5),
            size: 20,
          ),
          const SizedBox(width: 12),
          Expanded(
            child: Text(
              amenity.label,
              style: GoogleFonts.inter(
                fontSize: 15,
                color: isIncluded
                    ? GoOutsColors.bodyText
                    : GoOutsColors.bodyText.withValues(alpha: 0.6),
                decoration: isIncluded
                    ? TextDecoration.none
                    : TextDecoration.lineThrough,
              ),
            ),
          ),
        ],
      ),
    );
  }
}
